    34
    35  type TaskPreviewProps = WithCurrentUserPersonalDetailsProps & {
    36      /** The ID of the associated policy */
    37      // eslint-disable-next-line react/no-unused-prop-types
    38      policyID: string;
    39      /** The ID of the associated taskReport */
    40      taskReportID: string;
    41
    42      /** Whether the task preview is hovered so we can modify its style */
    43      isHovered: boolean;
    44
    45      /** The linked reportAction */
    46      action: OnyxEntry<ReportAction>;
    47
    48      /** The chat report associated with taskReport */
    49      chatReportID: string;
    50
    51      /** Popover context menu anchor, used for showing context menu */
    52      contextMenuAnchor: ContextMenuAnchor;
    53
    54      /** Callback for updating context menu active state, used for showing context menu */
    55      checkIfContextMenuActive: () => void;
    56  };
    57
    58  function TaskPreview({taskReportID, action, contextMenuAnchor, chatReportID, checkIfContextMenuActive, currentUserPersonalDetails, isHovered = false}: TaskPreviewProps) {
    59      const styles = useThemeStyles();
    60      const StyleUtils = useStyleUtils();
    61      const {translate} = useLocalize();
    62      const theme = useTheme();
    63      const [taskReport] = useOnyx(`${ONYXKEYS.COLLECTION.REPORT}${taskReportID}`);
    64
    65      // The reportAction might not contain details regarding the taskReport
    66      // Only the direct parent reportAction will contain details about the taskReport
    67      // Other linked reportActions will only contain the taskReportID and we will grab the details from there
    68      const isTaskCompleted = !isEmptyObject(taskReport)
    69          ? taskReport?.stateNum === CONST.REPORT.STATE_NUM.APPROVED && taskReport.statusNum === CONST.REPORT.STATUS_NUM.APPROVED
    70          : action?.childStateNum === CONST.REPORT.STATE_NUM.APPROVED && action?.childStatusNum === CONST.REPORT.STATUS_NUM.APPROVED;
    71      const taskTitle = Str.htmlEncode(TaskUtils.getTaskTitle(taskReportID, action?.childReportName ?? ''));
    72      const taskAssigneeAccountID = Task.getTaskAssigneeAccountID(taskReport) ?? action?.childManagerAccountID ?? '-1';
    73      const htmlForTaskPreview =
    74          taskAssigneeAccountID !== 0 ? `<comment><mention-user accountid="${taskAssigneeAccountID}"></mention-user> ${taskTitle}</comment>` : `<comment>${taskTitle}</comment>`;
    75      const isDeletedParentAction = ReportUtils.isCanceledTaskReport(taskReport, action);
    76      const shouldShowGreenDotIndicator = ReportUtils.isOpenTaskReport(taskReport, action) && ReportUtils.isReportManager(taskReport);
    77      if (isDeletedParentAction) {
    78          return <RenderHTML html={`<comment>${translate('parentReportAction.deletedTask')}</comment>`} />;
    79      }
    80
    81      return (
    82          <View style={[styles.chatItemMessage]}>
    83              <PressableWithoutFeedback
    84                  onPress={() => Navigation.navigate(ROUTES.REPORT_WITH_ID.getRoute(taskReportID))}
    85                  onPressIn={() => DeviceCapabilities.canUseTouchScreen() && ControlSelection.block()}
    86                  onPressOut={() => ControlSelection.unblock()}
    87                  onLongPress={(event) => showContextMenuForReport(event, contextMenuAnchor, chatReportID, action, checkIfContextMenuActive)}
    88                  shouldUseHapticsOnLongPress
    89                  style={[styles.flexRow, styles.justifyContentBetween]}
    90                  role={CONST.ROLE.BUTTON}
    91                  accessibilityLabel={translate('task.task')}
    92              >
    93                  <View style={[styles.flex1, styles.flexRow, styles.alignItemsStart]}>
    94                      <Checkbox
    95                          style={[styles.mr2]}
    96                          containerStyle={[styles.taskCheckbox]}
    97                          isChecked={isTaskCompleted}
    98                          disabled={!Task.canModifyTask(taskReport, currentUserPersonalDetails.accountID)}
    99                          onPress={Session.checkIfActionIsAllowed(() => {
   100                              if (isTaskCompleted) {
   101                                  Task.reopenTask(taskReport);
   102                              } else {
   103                                  Task.completeTask(taskReport);
   104                              }
   105                          })}
   106                          accessibilityLabel={translate('task.task')}
   107                      />
   108                      <RenderHTML html={isTaskCompleted ? `<completed-task>${htmlForTaskPreview}</completed-task>` : htmlForTaskPreview} />
   109                  </View>
   110                  {shouldShowGreenDotIndicator && (
   111                      <View style={styles.ml2}>
   112                          <Icon
   113                              src={Expensicons.DotIndicator}
   114                              fill={theme.success}
   115                          />
   116                      </View>
   117                  )}
   118                  <Icon
   119                      src={Expensicons.ArrowRight}
   120                      fill={StyleUtils.getIconFillColor(getButtonState(isHovered))}
   121                  />
   122              </PressableWithoutFeedback>
   123          </View>
   124      );
   125  }
   126
   127  TaskPreview.displayName = 'TaskPreview';
   128
   129  export default withCurrentUserPersonalDetails(TaskPreview);

