1  import React, {forwardRef} from 'react';
     2  import type {ForwardedRef, MouseEventHandler, KeyboardEvent as ReactKeyboardEvent} from 'react';
     3  import type {GestureResponderEvent, StyleProp, ViewStyle} from 'react-native';
     4  import {View} from 'react-native';
     5  import useStyleUtils from '@hooks/useStyleUtils';
     6  import useTheme from '@hooks/useTheme';
     7  import useThemeStyles from '@hooks/useThemeStyles';
     8  import CONST from '@src/CONST';
     9  import type ChildrenProps from '@src/types/utils/ChildrenProps';
    10  import Icon from './Icon';
    11  import * as Expensicons from './Icon/Expensicons';
    12  import PressableWithFeedback from './Pressable/PressableWithFeedback';
    13
    14  type CheckboxProps = Partial<ChildrenProps> & {
    15      /** Whether checkbox is checked */
    16      isChecked?: boolean;
    17
    18      /** A function that is called when the box/label is pressed */
    19      onPress: () => void;
    20
    21      /** Should the input be styled for errors  */
    22      hasError?: boolean;
    23
    24      /** Should the input be disabled  */
    25      disabled?: boolean;
    26
    27      /** Additional styles to add to checkbox button */
    28      style?: StyleProp<ViewStyle>;
    29
    30      /** Additional styles to add to checkbox container */
    31      containerStyle?: StyleProp<ViewStyle>;
    32
    33      /** Callback that is called when mousedown is triggered. */
    34      onMouseDown?: MouseEventHandler;
    35
    36      /** The size of the checkbox container */
    37      containerSize?: number;
    38
    39      /** The border radius of the checkbox container */
    40      containerBorderRadius?: number;
    41
    42      /** The size of the caret (checkmark) */
    43      caretSize?: number;
    44
    45      /** An accessibility label for the checkbox */
    46      accessibilityLabel: string;
    47
    48      /** stop propagation of the mouse down event */
    49      shouldStopMouseDownPropagation?: boolean;
    50  };
    51
    52  function Checkbox(
    53      {
    54          isChecked = false,
    55          hasError = false,
    56          disabled = false,
    57          style,
    58          containerStyle,
    59          children = null,
    60          onMouseDown,
    61          containerSize = 20,
    62          containerBorderRadius = 4,
    63          caretSize = 14,
    64          onPress,
    65          accessibilityLabel,
    66          shouldStopMouseDownPropagation,
    67      }: CheckboxProps,
    68      ref: ForwardedRef<View>,
    69  ) {
    70      const theme = useTheme();
    71      const styles = useThemeStyles();
    72      const StyleUtils = useStyleUtils();
    73
    74      const handleSpaceKey = (event?: ReactKeyboardEvent) => {
    75          if (event?.code !== 'Space') {
    76              return;
    77          }
    78
    79          onPress();
    80      };
    81
    82      const firePressHandlerOnClick = (event?: GestureResponderEvent | KeyboardEvent) => {
    83          // Pressable can be triggered with Enter key and by a click. As this is a checkbox,
    84          // We do not want to toggle it, when Enter key is pressed.
    85          if (event?.type && event.type !== 'click') {
    86              return;
    87          }
    88
    89          onPress();
    90      };
    91
    92      return (
    93          <PressableWithFeedback
    94              disabled={disabled}
    95              onPress={firePressHandlerOnClick}
    96              onMouseDown={(e) => {
    97                  if (shouldStopMouseDownPropagation) {
    98                      e.stopPropagation();
    99                  }
   100                  onMouseDown?.(e);
   101              }}
   102              ref={ref}
   103              style={[StyleUtils.getCheckboxPressableStyle(containerBorderRadius + 2), style]} // to align outline on focus, border-radius of pressable should be 2px more than Checkbox
   104              onKeyDown={handleSpaceKey}
   105              role={CONST.ROLE.CHECKBOX}
   106              aria-checked={isChecked}
   107              accessibilityLabel={accessibilityLabel}
   108              pressDimmingValue={1}
   109          >
   110              {children ?? (
   111                  <View
   112                      style={[
   113                          StyleUtils.getCheckboxContainerStyle(containerSize, containerBorderRadius),
   114                          containerStyle,
   115                          isChecked && styles.checkedContainer,
   116                          hasError && styles.borderColorDanger,
   117                          disabled && styles.cursorDisabled,
   118                          disabled && styles.buttonOpacityDisabled,
   119                          isChecked && styles.borderColorFocus,
   120                      ]}
   121                  >
   122                      {isChecked && (
   123                          <Icon
   124                              src={Expensicons.Checkmark}
   125                              fill={theme.textLight}
   126                              height={caretSize}
   127                              width={caretSize}
   128                          />
   129                      )}
   130                  </View>
   131              )}
   132          </PressableWithFeedback>
   133      );
   134  }
   135
   136  Checkbox.displayName = 'Checkbox';
   137
   138  export default forwardRef(Checkbox);
   139
   140  export type {CheckboxProps};

